import _ from 'lodash';
import type { Schema } from '../../../schema';
import { WORK_PROJECT_CATALOG } from '../constants/workProjectCatalog';
import { archive_tribe_log } from './tribeLog';

function complete_work_item(data: Schema, name: string, work: Schema['工作队列'][string]): void {
  const participants = [...work.具名指派];
  const efficiency_note =
    work.效率加成 > 0 ? `，效率 +${work.效率加成}%` : '';
  const member_note =
    participants.length > 0 ? `，参与：${participants.join('、')}` : '';

  if (work.类型 === '生产') {
    const existing = data.营地.物品栏[name];
    if (existing) {
      existing.数量 += 1;
    } else {
      data.营地.物品栏[name] = { 数量: 1, 描述: `${name}（生产完成）` };
    }
  }

  if (work.类型 === '建造') {
    const building = data.营地.当前建筑[name];
    if (building) {
      building.建筑阶段 = '已建成';
      building.状态 = '完好';
    }
  }

  if (work.类型 === '研发') {
    const project = WORK_PROJECT_CATALOG.find(p => p.name === name);
    if (project && !data.已解锁科技.includes(name)) {
      data.已解锁科技.push(name);
    }
    data.世界.当前研发 = '无';
    data.世界.研发进度 = 0;
  }

  const type_label: Record<Schema['工作队列'][string]['类型'], string> = {
    生产: '完成生产',
    建造: '完成建造',
    研发: '完成研发',
    学习: '完成学习',
  };

  archive_tribe_log(data, {
    类型: '工作',
    关联键: name,
    说明: `${work.类型}：${name}`,
    归档摘要: `${data.世界.兽历} ${data.世界.时间}：${type_label[work.类型]}「${name}」${efficiency_note}${member_note}`,
    具名参与: participants,
  });

  delete data.工作队列[name];
  console.info('[工作队列] 已完成并结算:', name);
}

function advance_work_item(
  data: Schema,
  name: string,
  work: Schema['工作队列'][string],
  hours: number,
): void {
  if (work.状态 !== '进行中' || work.具名指派.length === 0) {
    return;
  }

  const required = Math.max(0.1, work.所需工时 || 1);
  const efficiency = 1 + work.效率加成 / 100;
  const base = data.营地.无名族人基准效率 / 100;
  const effective_hours = hours * efficiency * base;
  const delta = (effective_hours / required) * 100;

  if (delta <= 0) {
    return;
  }

  work.进度 = _.clamp(work.进度 + delta, 0, 100);
  if (work.进度 >= 100) {
    complete_work_item(data, name, work);
  }
}

/** 推进工作队列进度（由 worldTimeTick 传入已结算的 hours） */
export function sync_work_queue_hours(data: Schema, hours: number): boolean {
  if (hours <= 0) {
    return false;
  }

  let changed = false;
  for (const name of Object.keys(data.工作队列)) {
    const work = data.工作队列[name];
    if (!work) {
      continue;
    }
    const before = work.进度;
    advance_work_item(data, name, work, hours);
    const after = data.工作队列[name];
    if (!after || after.进度 !== before) {
      changed = true;
    }
  }
  return changed;
}
